def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_my, last_opp = history[-1]

    opp_c = 0
    for _, o in history:
        if o == 'C':
            opp_c += 1
    opp_d = n - opp_c

    recent = history[-12:]
    rec_len = len(recent)
    rec_opp_c = sum(1 for _, o in recent if o == 'C')
    rec_opp_d = rec_len - rec_opp_c

    ignored = 0
    punished = 0
    for i in range(n - 1):
        if history[i][0] == 'D':
            if history[i + 1][1] == 'C':
                ignored += 1
            else:
                punished += 1

    stable = 0
    for m, o in reversed(history):
        if m == 'C' and o == 'C':
            stable += 1
        else:
            break

    opp_streak = 0
    for _, o in reversed(history):
        if o == 'D':
            opp_streak += 1
        else:
            break

    if n < 4:
        if last_opp == 'D' and opp_d >= 2:
            return 'D'
        return 'C'

    if opp_c == 0:
        return 'D'

    high_coop = opp_c * 100 >= n * 70
    evidence = high_coop and ignored > punished and rec_opp_c >= 8

    if evidence and not (last_opp == 'D' and rec_opp_d >= 5):
        return 'D'

    if n >= 96:
        if last_opp == 'D':
            return 'D'
        if n >= 98:
            return 'D'
        return 'C'

    if last_opp == 'D':
        if last_my == 'D':
            if opp_c * 100 >= n * 40:
                if rec_opp_c == 0 and opp_c * 100 < n * 25:
                    return 'D'
                if opp_streak >= 12 and opp_c * 100 < n * 35:
                    return 'D'
                return 'C'
            return 'D'

        if opp_streak >= 6 and rec_opp_c <= 6:
            return 'D'

        if high_coop and opp_d <= 6 and rec_opp_c >= 6:
            if rng.random() < 0.95:
                return 'C'
            return 'D'

        if opp_d * 100 >= n * 70 or rec_opp_d >= 7:
            return 'D'

        if high_coop and rec_opp_c >= 8:
            if rng.random() < 0.70:
                return 'C'
            return 'D'

        if opp_d <= 3:
            return 'C'

        if rng.random() < 0.15:
            return 'C'
        return 'D'

    if last_my == 'D':
        if high_coop and ignored > 0 and rec_opp_c >= 7:
            return 'D'
        return 'C'

    if high_coop and ignored > punished and stable >= 5:
        return 'D'

    if (stable >= 12 and opp_c * 100 >= n * 75 and 3 <= opp_d <= 8 and
            ignored == 0 and punished == 0 and rec_opp_c >= 10):
        if rng.random() < 0.35:
            return 'D'

    if opp_d * 100 >= n * 70:
        if stable <= 1:
            return 'D'
        if rng.random() < 0.65:
            return 'D'

    return 'C'
